def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.asarray(grid, dtype=int)
    h, w = g.shape
    out = np.full((h, w), 8, dtype=int)

    def mark(*cells):
        for r, c in cells:
            if 0 <= r < h and 0 <= c < w:
                out[r, c] = 2

    # Key column: the 4/2 vertical marker selects one column.
    key_col = None
    for r in range(h):
        for c in range(w):
            if g[r, c] == 4:
                key_col = c
                break
        if key_col is not None:
            break

    if key_col is not None:
        start = 0
        for r in range(h - 1, -1, -1):
            if g[r, key_col] in (1, 3):
                start = r
                break
        for r in range(start, h):
            out[r, key_col] = 2

    # Detect all compact 1/3 objects and emit their directional beams.
    nonbg = np.isin(g, [1, 3])
    visited = np.zeros((h, w), dtype=bool)
    for r0 in range(h):
        for c0 in range(w):
            if nonbg[r0, c0] and not visited[r0, c0]:
                stack = [(r0, c0)]
                comp = set()
                while stack:
                    r, c = stack.pop()
                    if not (0 <= r < h and 0 <= c < w):
                        continue
                    if not nonbg[r, c] or visited[r, c]:
                        continue
                    visited[r, c] = True
                    comp.add((r, c))
                    stack.extend([(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)])

                rows = [r for r, _ in comp]
                cols = [c for _, c in comp]
                min_r, max_r = min(rows), max(rows)
                min_c, max_c = min(cols), max(cols)
                if (max_r - min_r + 1) * (max_c - min_c + 1) <= 20:
                    for r, c in comp:
                        out[r, c] = 2

                    # For each 3 marker, paint the corresponding outward beam
                    # until hitting the border, the key column, or another object.
                    for r, c in comp:
                        if g[r, c] != 3:
                            continue

                        rr, cc = r, c
                        if max_r - min_r > 0 and max_r == r:       # bottom
                            while rr + 1 < h and out[rr + 1, c] == 8 and g[rr + 1, c] == 8 and c != key_col:
                                rr += 1
                                out[rr, c] = 2
                        elif min_r == r:                            # top
                            while rr - 1 >= 0 and out[rr - 1, c] == 8 and g[rr - 1, c] == 8 and c != key_col:
                                rr -= 1
                                out[rr, c] = 2
                        elif max_c - min_c > 0 and max_c == c:      # right
                            while cc + 1 < w and out[r, cc + 1] == 8 and g[r, cc + 1] == 8 and r != key_col:
                                cc += 1
                                out[r, cc] = 2
                        elif min_c == c:                            # left
                            while cc - 1 >= 0 and out[r, cc - 1] == 8 and g[r, cc - 1] == 8 and r != key_col:
                                cc -= 1
                                out[r, cc] = 2

    return out.tolist()

