def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.asarray(grid, dtype=int)
    H, W = g.shape
    out = np.full((H, W), 8, dtype=int)

    # Locate the 4/2 selector column.
    key_col = None
    for r in range(H):
        for c in range(W):
            if g[r, c] == 4:
                key_col = c
                break
        if key_col is not None:
            break

    # All 1/3 cells are part of objects; they become 2 if their component is active.
    object_mask = np.isin(g, [1, 3])

    # Build 4-connected components of objects.
    visited = np.zeros((H, W), dtype=bool)
    comps = []
    for r in range(H):
        for c in range(W):
            if object_mask[r, c] and not visited[r, c]:
                stack = [(r, c)]
                cells = []
                while stack:
                    rr, cc = stack.pop()
                    if not (0 <= rr < H and 0 <= cc < W):
                        continue
                    if not object_mask[rr, cc] or visited[rr, cc]:
                        continue
                    visited[rr, cc] = True
                    cells.append((rr, cc))
                    stack.extend([(rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)])
                if cells:
                    comps.append(cells)

    # For each component, find its 3-side direction and edge cells.
    comp_dir = {}
    comp_edge = {}
    for idx, cells in enumerate(comps):
        rows = [r for r, _ in cells]
        cols = [c for _, c in cells]
        min_r, max_r = min(rows), max(rows)
        min_c, max_c = min(cols), max(cols)

        top_edge = [(r, c) for r, c in cells if r == min_r and g[r, c] == 3]
        bottom_edge = [(r, c) for r, c in cells if r == max_r and g[r, c] == 3]
        left_edge = [(r, c) for r, c in cells if c == min_c and g[r, c] == 3]
        right_edge = [(r, c) for r, c in cells if c == max_c and g[r, c] == 3]

        d, edge = None, []
        if top_edge:
            d, edge = 'up', top_edge
        elif bottom_edge:
            d, edge = 'down', bottom_edge
        elif left_edge:
            d, edge = 'left', left_edge
        elif right_edge:
            d, edge = 'right', right_edge

        comp_dir[idx] = d
        comp_edge[idx] = edge

    # Determine if a component contains/intersects the selector column.
    def intersects_key(idx):
        if key_col is None:
            return False
        return any(c == key_col for _, c in comps[idx])

    # Shoot a component's 3-edge ray and return whether it reaches another object
    # or the selector column.  The ray starts just outside the component edge.
    def ray_hits(idx):
        d = comp_dir[idx]
        if d is None:
            return False
        edge = comp_edge[idx]
        rows = [r for r, _ in comps[idx]]
        cols = [c for _, c in comps[idx]]
        min_r, max_r = min(rows), max(rows)
        min_c, max_c = min(cols), max(cols)

        # For horizontal rays, the relevant rows are the 3 cells' rows.
        # For vertical rays, the relevant columns are the 3 cells' columns.
        if d == 'up':
            for c in sorted({c for _, c in edge}):
                r = min_r - 1
                while r >= 0:
                    if object_mask[r, c] or (key_col is not None and c == key_col):
                        return True
                    r -= 1
        elif d == 'down':
            for c in sorted({c for _, c in edge}):
                r = max_r + 1
                while r < H:
                    if object_mask[r, c] or (key_col is not None and c == key_col):
                        return True
                    r += 1
        elif d == 'left':
            for r in sorted({r for r, _ in edge}):
                c = min_c - 1
                while c >= 0:
                    if object_mask[r, c] or (key_col is not None and r == key_col):
                        return True
                    c -= 1
        elif d == 'right':
            for r in sorted({r for r, _ in edge}):
                c = max_c + 1
                while c < W:
                    if object_mask[r, c] or (key_col is not None and r == key_col):
                        return True
                    c += 1
        return False

    # Active components: start from components that intersect the selector column,
    # then activate any component reached by their rays, recursively.
    active = [False] * len(comps)
    changed = True
    while changed:
        changed = False
        for i in range(len(comps)):
            if active[i] or intersects_key(i):
                if not active[i]:
                    active[i] = True
                    changed = True
                if ray_hits(i):
                    # Activate any component hit by this ray.
                    for j in range(len(comps)):
                        if j == i or active[j]:
                            continue
                        # Check hit relation from i to j.
                        d = comp_dir[i]
                        if d is None:
                            continue
                        edge = comp_edge[i]
                        rows_i = [r for r, _ in comps[i]]
                        cols_i = [c for _, c in comps[i]]
                        min_r, max_r = min(rows_i), max(rows_i)
                        min_c, max_c = min(cols_i), max(cols_i)

                        rows_j = [r for r, _ in comps[j]]
                        cols_j = [c for _, c in comps[j]]
                        min_rj, max_rj = min(rows_j), max(rows_j)
                        min_cj, max_cj = min(cols_j), max(cols_j)

                        hit = False
                        if d == 'up':
                            for c in cols_i:
                                if min_rj < min_r and min_cj <= c <= max_cj:
                                    hit = True
                        elif d == 'down':
                            for c in cols_i:
                                if max_rj > max_r and min_cj <= c <= max_cj:
                                    hit = True
                        elif d == 'left':
                            for r in rows_i:
                                if max_cj < min_c and min_rj <= r <= max_rj:
                                    hit = True
                        elif d == 'right':
                            for r in rows_i:
                                if min_rj <= r <= max_rj and min_cj > max_c:
                                    hit = True
                        if hit:
                            active[j] = True
                            changed = True

    # Paint active object bodies.
    for idx, cells in enumerate(comps):
        if not active[idx]:
            continue
        for r, c in cells:
            out[r, c] = 2

    # Paint active rays outward, stopping at objects or grid border.
    for idx, cells in enumerate(comps):
        if not active[idx]:
            continue
        d = comp_dir[idx]
        edge = comp_edge[idx]
        if not edge:
            continue
        rows = [r for r, _ in cells]
        cols = [c for _, c in cells]
        min_r, max_r = min(rows), max(rows)
        min_c, max_c = min(cols), max(cols)

        if d == 'up':
            for c in sorted({c for _, c in edge}):
                r = min_r - 1
                while r >= 0 and not object_mask[r, c]:
                    out[r, c] = 2
                    r -= 1
        elif d == 'down':
            for c in sorted({c for _, c in edge}):
                r = max_r + 1
                while r < H and not object_mask[r, c]:
                    out[r, c] = 2
                    r += 1
        elif d == 'left':
            for r in sorted({r for r, _ in edge}):
                c = min_c - 1
                while c >= 0 and not object_mask[r, c]:
                    out[r, c] = 2
                    c -= 1
        elif d == 'right':
            for r in sorted({r for r, _ in edge}):
                c = max_c + 1
                while c < W and not object_mask[r, c]:
                    out[r, c] = 2
                    c += 1

    # Selector column behavior: fill it from the nearest active object above
    # (or from the top if none), down to the bottom.
    if key_col is not None:
        fill_top = 0
        active_rows = [r for idx, cells in enumerate(comps) if active[idx] for r, _ in cells if _ == key_col]
        if active_rows:
            fill_top = min(active_rows)

        # Also fill from the selector marker itself upward to the first active object.
        marker_rows = [r for r in range(H) if g[r, key_col] == 4]
        if marker_rows:
            start = min(marker_rows)
            for r in range(start, H):
                out[r, key_col] = 2
            for r in range(start - 1, -1, -1):
                if object_mask[r, key_col]:
                    # Fill up to and including this object if it is active.
                    if any(active[idx] for idx, cells in enumerate(comps)
                           for rr, cc in cells if rr == r and cc == key_col):
                        out[r, key_col] = 2
                        fill_top = min(fill_top, r)
                    break
                out[r, key_col] = 2

        for r in range(fill_top, H):
            out[r, key_col] = 2

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    h = len(grid)
    w = len(grid[0])
    g = [[int(c) for c in row] for row in grid]

    def set_cell(out, r, c, v):
        if 0 <= r < len(out) and 0 <= c < len(out[0]):
            out[r][c] = v

    def has_7(rect):
        r0, c0, r1, c1 = rect
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if g[r][c] == 7:
                    return True
        return False

    def candidate_output(keep_rect, donor_rect, anchor, orientation, out_h, out_w):
        kr0, kc0, kr1, kc1 = keep_rect
        dr0, dc0, dr1, dc1 = donor_rect

        out = [[1] * out_w for _ in range(out_h)]
        off_r = -kr0
        off_c = -kc0

        # Copy the main keep region.
        for r in range(kr0, kr1 + 1):
            for c in range(kc0, kc1 + 1):
                v = g[r][c]
                if v == 7:
                    v = 4
                out[r + off_r][c + off_c] = v

        dh = dr1 - dr0 + 1
        dw = dc1 - dc0 + 1
        ar, ac = anchor
        br, bc = ar + off_r, ac + off_c

        # Apply donor pattern. 7 is treated as 4.
        for dr in range(dh):
            for dc in range(dw):
                v = g[dr0 + dr][dc0 + dc]
                if v == 7:
                    v = 4
                if v == 1:
                    continue

                if orientation == "up":
                    rr, cc = br + dr, bc + dc
                elif orientation == "down":
                    rr, cc = br - dr, bc + dc
                elif orientation == "left":
                    rr, cc = br + dr, bc + dc
                else:  # right
                    rr, cc = br + dr, bc + dc

                set_cell(out, rr, cc, v)
        return out

    def score(o):
        # Prefer valid outputs, fewer 7s, and fewer odd 1-cells.
        sevens = 0
        odd_ones = 0
        for r, row in enumerate(o):
            for c, v in enumerate(row):
                if v == 7:
                    sevens += 1
                if v == 1:
                    odd_ones += (r + c) & 1
        return (sevens, odd_ones)

    # Try every possible keep rectangle and every possible donor rectangle.
    # This is small for the given puzzles and also handles unseen test grids.
    best = None
    best_key = None

    for kr0 in range(h):
        for kr1 in range(kr0, h):
            for kc0 in range(w):
                for kc1 in range(kc0, w):
                    keep = (kr0, kc0, kr1, kc1)
                    if not has_7(keep):
                        continue

                    # Determine output size from the keep rectangle.
                    out_h = kr1 - kr0 + 1
                    out_w = kc1 - kc0 + 1

                    # For this keep rectangle, try possible donor rectangles.
                    for dr0 in range(h):
                        for dr1 in range(dr0, h):
                            for dc0 in range(w):
                                for dc1 in range(dc0, w):
                                    donor = (dr0, dc0, dr1, dc1)
                                    if not has_7(donor):
                                        continue

                                    # Possible anchor positions for the donor
                                    # relative to the keep/donor 7 pattern.
                                    anchors = [(dr0, dc0), (dr1, dc1),
                                               (dr0, dc1), (dr1, dc0)]
                                    # Also add a few practical offsets.
                                    for extra_r in range(-1, 2):
                                        for extra_c in range(-1, 2):
                                            anchors.append((dr0 + extra_r, dc0 + extra_c))
                                            anchors.append((dr1 + extra_r, dc1 + extra_c))

                                    for ar, ac in anchors:
                                        for orient in ("up", "down", "left", "right"):
                                            try:
                                                cand = candidate_output(keep, donor, (ar, ac), orient, out_h, out_w)
                                            except Exception:
                                                continue
                                            key = score(cand)
                                            if best_key is None or key < best_key:
                                                best_key = key
                                                best = cand

    if best is None:
        # Fallback: replace all 7 by 4.
        return [[4 if v == 7 else v for v in row] for row in g]

    return best

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    H, W = a.shape
    out = a.copy()

    # Find all maximal all-zero rectangular rooms.
    visited = np.zeros((H, W), dtype=bool)

    for r in range(H):
        for c in range(W):
            if a[r, c] != 0 or visited[r, c]:
                continue

            # Expand to maximal zero rectangle starting at (r, c)
            r2 = r
            while r2 + 1 < H and a[r2 + 1, c] == 0:
                r2 += 1
            c2 = c
            while c2 + 1 < W and a[r, c2 + 1] == 0:
                c2 += 1
            # verify rectangle
            ok = True
            for rr in range(r, r2 + 1):
                for cc in range(c, c2 + 1):
                    if a[rr, cc] != 0:
                        ok = False
                        break
                if not ok:
                    break
            if not ok:
                continue

            h = r2 - r + 1
            w = c2 - c + 1

            # Mark whole rectangle
            for rr in range(r, r2 + 1):
                for cc in range(c, c2 + 1):
                    visited[rr, cc] = True

            # Collect candidate directions that lead to a contiguous all-6 region
            # of exactly the same size, with a matching 9 line on the far side
            # of that region and no 9 line on the starting side.
            cands = []

            # Up
            if r - h >= 0:
                good = True
                for rr in range(r - h, r):
                    for cc in range(c, c + w):
                        if a[rr, cc] != 6:
                            good = False
                            break
                    if not good:
                        break
                if good:
                    start_ok = True
                    far_ok = True
                    if r > 0:
                        for cc in range(c, c + w):
                            if a[r - 1, cc] == 9:
                                start_ok = False
                    if r - h - 1 >= 0:
                        for cc in range(c, c + w):
                            if a[r - h - 1, cc] == 9:
                                far_ok = True
                                break
                        else:
                            far_ok = False
                    else:
                        far_ok = False
                    if start_ok and far_ok:
                        cands.append((0, -h))

            # Down
            if r2 + h < H:
                good = True
                for rr in range(r2 + 1, r2 + h + 1):
                    for cc in range(c, c + w):
                        if a[rr, cc] != 6:
                            good = False
                            break
                    if not good:
                        break
                if good:
                    start_ok = True
                    far_ok = True
                    if r2 < H - 1:
                        for cc in range(c, c + w):
                            if a[r2 + 1, cc] == 9:
                                start_ok = False
                    if r2 + h < H:
                        for cc in range(c, c + w):
                            if a[r2 + h, cc] == 9:
                                far_ok = True
                                break
                        else:
                            far_ok = False
                    else:
                        far_ok = False
                    if start_ok and far_ok:
                        cands.append((h, 0))

            # Left
            if c - w >= 0:
                good = True
                for cc in range(c - w, c):
                    for rr in range(r, r + h):
                        if a[rr, cc] != 6:
                            good = False
                            break
                    if not good:
                        break
                if good:
                    start_ok = True
                    far_ok = True
                    if c > 0:
                        for rr in range(r, r + h):
                            if a[rr, c - 1] == 9:
                                start_ok = False
                    if c - w - 1 >= 0:
                        for rr in range(r, r + h):
                            if a[rr, c - w - 1] == 9:
                                far_ok = True
                                break
                        else:
                            far_ok = False
                    else:
                        far_ok = False
                    if start_ok and far_ok:
                        cands.append((0, -w))

            # Right
            if c2 + w < W:
                good = True
                for cc in range(c2 + 1, c2 + w + 1):
                    for rr in range(r, r + h):
                        if a[rr, cc] != 6:
                            good = False
                            break
                    if not good:
                        break
                if good:
                    start_ok = True
                    far_ok = True
                    if c2 < W - 1:
                        for rr in range(r, r + h):
                            if a[rr, c2 + 1] == 9:
                                start_ok = False
                    if c2 + w < W:
                        for rr in range(r, r + h):
                            if a[rr, c2 + w] == 9:
                                far_ok = True
                                break
                        else:
                            far_ok = False
                    else:
                        far_ok = False
                    if start_ok and far_ok:
                        cands.append((0, w))

            # Prefer the smallest shift.  The examples are consistent with this.
            if cands:
                cands.sort(key=lambda x: x[0] + x[1])
                dr, dc = cands[0]

                # Original room becomes 6
                out[r:r + h, c:c + w] = 6

                # New room location
                nr, nc = r + dr, c + dc
                block = a[r:r + h, c:c + w]
                block = block[::-1, ::-1]  # rotate 180
                block = block.copy()
                block[block == 5] = 7
                block[block == 7] = 5
                out[nr:nr + h, nc:nc + w] = block

    return out.tolist()

import numpy as np
from collections import deque

def _rect_from(a, start):
    r, c = start
    r1 = r
    while r1 + 1 < a.shape[0] and a[r1 + 1, c] == 0:
        r1 += 1
    c1 = c
    while c1 + 1 < a.shape[1] and a[r, c1 + 1] == 0:
        c1 += 1
    for rr in range(r, r1 + 1):
        for cc in range(c, c1 + 1):
            if a[rr, cc] != 0:
                return None
    return (r, c, r1, c1)

def _contiguous_rect(a, r, c, h, w):
    for rr in range(r, r + h):
        for cc in range(c, c + w):
            if a[rr, cc] not in (0, 5, 7):
                return False
    return True

def _line9(a, r, c, h, w, side):
    if side == 'U':
        if r < 0: return False
        for cc in range(c, c + w):
            if a[r - 1, cc] != 9:
                return False
    elif side == 'D':
        if r + h >= a.shape[0]: return False
        for cc in range(c, c + w):
            if a[r + h, cc] != 9:
                return False
    elif side == 'L':
        if c < 0: return False
        for rr in range(r, r + h):
            if a[rr, c - 1] != 9:
                return False
    elif side == 'R':
        if c + w >= a.shape[1]: return False
        for rr in range(r, r + h):
            if a[rr, c + w] != 9:
                return False
    return True

def _line_not9(a, r, c, h, w, side):
    if side == 'U':
        if r < 0: return False
        for cc in range(c, c + w):
            if a[r - 1, cc] == 9:
                return False
    elif side == 'D':
        if r + h >= a.shape[0]: return False
        for cc in range(c, c + w):
            if a[r + h, cc] == 9:
                return False
    elif side == 'L':
        if c < 0: return False
        for rr in range(r, r + h):
            if a[rr, c - 1] == 9:
                return False
    elif side == 'R':
        if c + w >= a.shape[1]: return False
        for rr in range(r, r + h):
            if a[rr, c + w] == 9:
                return False
    return True

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=np.int64)
    H, W = a.shape
    out = a.copy()

    # Identify maximal all-zero rectangles.
    visited = np.zeros((H, W), dtype=bool)
    rooms = []
    for r in range(H):
        for c in range(W):
            if a[r, c] == 0 and not visited[r, c]:
                rect = _rect_from(a, (r, c))
                if rect is None:
                    visited[r, c] = True
                    continue
                r0, c0, r1, c1 = rect
                for rr in range(r0, r1 + 1):
                    for cc in range(c0, c1 + 1):
                        visited[rr, cc] = True
                h = r1 - r0 + 1
                w = c1 - c0 + 1
                has_content = np.any((a[r0:r1 + 1, c0:c1 + 1] == 5) |
                                     (a[r0:r1 + 1, c0:c1 + 1] == 7))
                if h >= 3 and w >= 3 and has_content:
                    rooms.append((r0, c0, r1, c1))

    moves = []
    for r0, c0, r1, c1 in rooms:
        h = r1 - r0 + 1
        w = c1 - c0 + 1
        cands = []

        for dr, dc, side_from, side_far in (
            (-h, 0, 'U', 'D'),
            ( h, 0, 'D', 'U'),
            (0, -w, 'L', 'R'),
            (0,  w, 'R', 'L'),
        ):
            nr0, nc0 = r0 + dr, c0 + dc
            nr1, nc1 = r1 + dr, c1 + dc
            if nr0 < 0 or nc0 < 0 or nr1 >= H or nc1 >= W:
                continue
            if not _contiguous_rect(a, nr0, nc0, h, w):
                continue
            if not _line9(a, nr0, nc0, h, w, side_far):
                continue
            if not _line_not9(a, r0, c0, h, w, side_from):
                continue
            cands.append((dr, dc))

        if cands:
            cands.sort(key=lambda x: x[0] + x[1])
            moves.append((r0, c0, r1, c1, cands[0]))

    if not moves:
        return out.tolist()

    # For each moving room, compute where 5s should become 7s.
    for r0, c0, r1, c1, (dr, dc) in moves:
        h = r1 - r0 + 1
        w = c1 - c0 + 1
        block = a[r0:r1 + 1, c0:c1 + 1].copy()

        # Seeds: existing 7s inside the room.
        seeds = []
        for i in range(h):
            for j in range(w):
                if block[i, j] == 7:
                    seeds.append((i, j))

        # If no 7s, infer one seed from the final wall: the side/corner cell
        # closest to the wall in the direction of motion.
        if not seeds:
            if dr < 0:
                row = 0
            elif dr > 0:
                row = h - 1
            else:
                row = 0
            if dc < 0:
                col = 0
            elif dc > 0:
                col = w - 1
            else:
                col = 0
            seeds.append((row, col))

        # Flood fill 4-neighbor through 5 cells, but only convert cells that
        # are on the destination wall side/corner.
        convert = np.zeros((h, w), dtype=bool)
        q = deque(seeds)
        seen = np.zeros((h, w), dtype=bool)
        for sr, sc in seeds:
            seen[sr, sc] = True
            convert[sr, sc] = True

        while q:
            r, c = q.popleft()
            for rr, cc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if 0 <= rr < h and 0 <= cc < w and not seen[rr, cc]:
                    if block[rr, cc] == 5:
                        seen[rr, cc] = True
                        on_wall = False
                        if dr < 0 and rr == 0:
                            on_wall = True
                        elif dr > 0 and rr == h - 1:
                            on_wall = True
                        elif dc < 0 and cc == 0:
                            on_wall = True
                        elif dc > 0 and cc == w - 1:
                            on_wall = True

                        if on_wall:
                            convert[rr, cc] = True
                            q.append((rr, cc))

        # Write transformed block to the destination.
        nr0, nc0 = r0 + dr, c0 + dc
        dest = out[nr0:nr0 + h, nc0:nc0 + w]
        dest[dest == 5] = 0
        dest[dest == 7] = 0
        dest[convert] = 7
        dest[(block == 5) & (~convert)] = 5
        dest[(block == 7) | convert] = 7

        # Original room becomes background 6.
        out[r0:r1 + 1, c0:c1 + 1] = 6

        # Put back the final contents.
        out[nr0:nr0 + h, nc0:nc0 + w] = dest

    return out.tolist()

