def transform(grid: list[list[int]]) -> list[list[int]):
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    a = [list(map(int, row)) for row in grid]
    H, W = len(a), len(a[0])
    out = [row[:] for row in a]

    def runs_from_outward(seq: list[int]):
        # seq is ordered from the line outward.
        runs = []
        i = 0
        n = len(seq)
        while i < n:
            if seq[i] == 0:
                i += 1
                continue
            j = i
            while j + 1 < n and seq[j + 1] == seq[i]:
                j += 1
            runs.append((seq[i], j - i + 1, i))  # color, length, start distance from line
            i = j + 1
        return runs

    def fill_target(target: list[int], runs: list[tuple[int, int, int]]) -> list[int]:
        # target is ordered from the line outward.
        n = len(target)
        res = [0] * n
        for p in range(n):
            best_color = 0
            best_priority = None
            for color, length, start in runs:
                if length > 0 and p % length == 0:
                    # nearer source run (smaller start) wins; tie: shorter run, then smaller color
                    priority = (start, length, color)
                    if best_priority is None or priority < best_priority:
                        best_priority = priority
                        best_color = color
            res[p] = best_color
        return res

    def vertical(c: int, color: int, src_left: bool) -> list[list[int]]:
        b = [row[:] for row in a]
        Wc = W - c - 1
        Lc = c
        for r in range(H):
            if src_left:
                src = [a[r][c - 1 - d] for d in range(Lc)]
                tgt_len = Wc
            else:
                src = [a[r][c + 1 + d] for d in range(Wc)]
                tgt_len = Lc

            runs = runs_from_outward(src)
            filled = fill_target([0] * tgt_len, runs)

            if src_left:
                for d, val in enumerate(filled):
                    b[r][c + 1 + d] = val
            else:
                for d, val in enumerate(filled):
                    b[r][c - 1 - d] = val
        return b

    def horizontal(r: int, color: int, src_up: bool) -> list[list[int]]:
        b = [row[:] for row in a]
        Hc = H - r - 1
        Ur = r
        for c in range(W):
            if src_up:
                src = [a[r - 1 - d][c] for d in range(Ur)]
                tgt_len = Hc
            else:
                src = [a[r + 1 + d][c] for d in range(Hc)]
                tgt_len = Ur

            runs = runs_from_outward(src)
            filled = fill_target([0] * tgt_len, runs)

            if src_up:
                for d, val in enumerate(filled):
                    b[r + 1 + d][c] = val
            else:
                for d, val in enumerate(filled):
                    b[r - 1 - d][c] = val
        return b

    # Detect the separator line and the side that contains the source bars.
    best = None  # (score, orientation, coord, color, src_left_or_up)

    def consider_vertical(c, color):
        nonlocal best
        left_nz = sum(1 for i in range(H) for j in range(c) if a[i][j] != 0)
        right_nz = sum(1 for i in range(H) for j in range(c + 1, W) if a[i][j] != 0)
        if left_nz == 0 and right_nz == 0:
            return
        line_count = sum(1 for i in range(H) if a[i][c] == color)
        target_nz = min(left_nz, right_nz)
        source_nz = max(left_nz, right_nz)
        # Prefer strong line, empty target side, and a clear source side.
        score = 1000 * line_count - 500 * target_nz + source_nz
        src_left = left_nz > right_nz
        if best is None or score > best[0]:
            best = (score, 'V', c, color, src_left)

    def consider_horizontal(r, color):
        nonlocal best
        up_nz = sum(1 for i in range(r) for j in range(W) if a[i][j] != 0)
        down_nz = sum(1 for i in range(r + 1, H) for j in range(W) if a[i][j] != 0)
        if up_nz == 0 and down_nz == 0:
            return
        line_count = sum(1 for j in range(W) if a[r][j] == color)
        target_nz = min(up_nz, down_nz)
        source_nz = max(up_nz, down_nz)
        score = 1000 * line_count - 500 * target_nz + source_nz
        src_up = up_nz > down_nz
        if best is None or score > best[0]:
            best = (score, 'H', r, color, src_up)

    # Try all plausible separator colors in all columns/rows.
    colors = set()
    for row in a:
        for v in row:
            if v != 0:
                colors.add(v)

    for c in range(W):
        col_counts = {}
        for i in range(H):
            v = a[i][c]
            if v != 0:
                col_counts[v] = col_counts.get(v, 0) + 1
        for v, cnt in col_counts.items():
            if cnt >= max(3, H // 2):
                consider_vertical(c, v)

    for r in range(H):
        row_counts = {}
        for j in range(W):
            v = a[r][j]
            if v != 0:
                row_counts[v] = row_counts.get(v, 0) + 1
        for v, cnt in row_counts.items():
            if cnt >= max(3, W // 2):
                consider_horizontal(r, v)

    if best is not None:
        _, orient, coord, color, src_first = best
        if orient == 'V':
            return vertical(coord, color, src_first)
        else:
            return horizontal(coord, color, src_first)

    return out

