from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    def nonzeros():
        return [(i, j, int(g[i, j])) for i in range(h) for j in range(w) if g[i, j] != 0]

    def bfs_color(x, y, color):
        q = deque([(x, y)])
        seen = {(x, y)}
        cells = []
        while q:
            i, j = q.popleft()
            cells.append((i, j))
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < h and 0 <= nj < w and (ni, nj) not in seen and g[ni, nj] == color:
                    seen.add((ni, nj))
                    q.append((ni, nj))
        return cells

    def bbox(cells):
        rr = [r for r,_ in cells]
        cc = [c for c,_ in cells]
        return min(rr), max(rr), min(cc), max(cc)

    cells = nonzeros()
    if not cells:
        return [[int(v) for v in row] for row in out]

    # Find a rectangular frame whose four borders contain at least 4 distinct border colors.
    best = None
    for r1 in range(h):
        for r2 in range(r1 + 2, h):
            for c1 in range(w):
                for c2 in range(c1 + 2, w):
                    border = set()
                    for j in range(c1, c2 + 1):
                        border.add(g[r1, j])
                        border.add(g[r2, j])
                    for i in range(r1, r2 + 1):
                        border.add(g[i, c1])
                        border.add(g[i, c2])
                    border.discard(0)
                    if len(border) < 4:
                        continue
                    score = (len(border), min(r2 - r1, c2 - c1), -(r1 * w + c1))
                    if best is None or score > best[0]:
                        best = (score, r1, r2, c1, c2)

    if best is None:
        # Fallback: no detectable frame, return input.
        return [[int(v) for v in row] for row in out]

    _, r1, r2, c1, c2 = best

    # Border color occurrences.
    def is_border(i, j):
        return i == r1 or i == r2 or j == c1 or j == c2

    positions_by_color = {}
    base_h = {}
    base_v = {}
    for i in range(r1, r2 + 1):
        for j in range(c1, c2 + 1):
            if is_border(i, j):
                color = int(g[i, j])
                positions_by_color.setdefault(color, set()).add((i, j))

    for color, pos in positions_by_color.items():
        rows = [i for i,j in pos]
        cols = [j for i,j in pos]
        # horizontal border row (top or bottom)
        for r in (r1, r2):
            if any(i == r for i, j in pos):
                base_h.setdefault(color, (r, min(cols)))
                base_h[color] = (r, min(j for i,j in pos if i == r))
                break
        # vertical border col (left or right)
        for c in (c1, c2):
            if any(j == c for i, j in pos):
                base_v.setdefault(color, (c, min(rows)))
                base_v[color] = (c, min(i for i,j in pos if j == c))
                break

    # Candidate source objects are connected components outside the frame.
    used = set()
    objects = {}
    for i, j, color in cells:
        if (i, j) in used:
            continue
        if r1 <= i <= r2 and c1 <= j <= c2:
            used.add((i, j))
            continue
        comp = bfs_color(i, j, color)
        used.update((a,b) for a,b in comp)
        rr1, rr2, cc1, cc2 = bbox(comp)
        if cc2 >= c1:  # touches/crosses frame
            continue
        # Only accept compact objects reasonably near the frame.
        width = cc2 - cc1 + 1
        height = rr2 - rr1 + 1
        if width <= 1 or height <= 1:
            continue
        if width > 7 or height > 7:
            continue
        if cc1 < 0 or rr1 < 0 or rr2 >= h:
            continue
        objects.setdefault(color, []).append((rr1, rr2, cc1, cc2, comp))

    # For each object color, choose target intersection from border markers.
    placements = []
    for color, obj_list in objects.items():
        if color not in positions_by_color:
            continue
        if color not in base_h or color not in base_v:
            continue
        top_row, top_col = base_h[color]
        left_col, left_row = base_v[color]

        # Choose object whose vertical center is closest to the frame's vertical marker row.
        def center_row(o):
            rr1, rr2, _, _, _ = o
            return (rr1 + rr2) / 2.0
        obj = min(obj_list, key=lambda o: (abs(center_row(o) - left_row), -len(o[4])))
        rr1, rr2, cc1, cc2, comp = obj
        cy = (rr1 + rr2) / 2.0
        cx = (cc1 + cc2) / 2.0

        target_row = left_row
        target_col = top_col

        # Translate the object so its bounding-box center maps to target.
        for (oi, oj) in comp:
            ni = round(oi - cy + target_row)
            nj = round(oj - cx + target_col)
            if r1 < ni < r2 and c1 < nj < c2:
                out[ni, nj] = color

    # Remove used source objects from outside area.
    for color, obj_list in objects.items():
        if color not in positions_by_color:
            continue
        if color not in base_h or color not in base_v:
            continue
        for (_, _, _, _, comp) in obj_list:
            for (i, j) in comp:
                if i < r1 or i > r2 or j < c1 or j > c2:
                    out[i, j] = 0

    return [[int(v) for v in row] for row in out]

