    mask = g != bg
    seen = np.zeros_like(mask, dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if mask[r, c] and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = [(r, c)]
                while q:
                    y, x = q.popleft()
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w and mask[ny, nx] and not seen[ny, nx]:
                                seen[ny, nx] = True
                                cells.append((ny, nx))
                                q.append((ny, nx))
                comps.append(cells)

    # A component is an anchor only if it is a single cell on the border.
    anchors = []
    for comp in comps:
        if len(comp) == 1:
            r, c = comp[0]
            if r == 0 or r == h - 1 or c == 0 or c == w - 1:
                anchors.append((r, c, int(g[r, c])))

    if not anchors:
        return [list(map(int, row)) for row in g]

    # For each non-anchor component, choose one border anchor colour present in it.
    # Prefer an anchor colour that appears exactly once in the component.
    # Movement axis is parallel to the border edge containing that anchor:
    # top/bottom => horizontal alignment by column; left/right => vertical alignment by row.
    moves = []
    for comp in comps:
        if len(comp) == 1:
            r, c = comp[0]
            if (r == 0 or r == h - 1 or c == 0 or c == w - 1) and (r, c, int(g[r, c])) in anchors:
                continue

        col_counts = {}
        for r, c in comp:
            col = int(g[r, c])
            col_counts[col] = col_counts.get(col, 0) + 1

        chosen = None
        for ar, ac, color in anchors:
            if color not in col_counts:
                continue
            if chosen is None or col_counts[color] < chosen[2]:
                chosen = (ar, ac, color)

        if chosen is None:
            continue

        ar, ac, color = chosen

        marker_cells = [(r, c) for r, c in comp if int(g[r, c]) == color]
        if not marker_cells:
            continue
        mr, mc = marker_cells[0]

        if ar == 0 or ar == h - 1:
            dr = 0
            dc = ac - mc
        else:
            dr = ar - mr
            dc = 0

        # Ensure the whole component fits and does not overlap any other component.
        comp_set = set(comp)
        other_cells = set()
        for other in comps:
            if other is not comp:
                other_cells.update(other)

        ok = True
        for r, c in comp:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < h and 0 <= nc < w):
                ok = False
                break
            if (nr, nc) not in comp_set and (nr, nc) in other_cells:
                ok = False
                break

        if ok:
            moves.append((comp, dr, dc))

    # Apply all valid moves simultaneously.
    out = np.full_like(g, bg)
    for comp, dr, dc in moves:
        for r, c in comp:
            out[r + dr, c + dc] = g[r, c]

    # Anchors stay exactly where they were.
    for r, c, color in anchors:
        out[r, c] = color

    return [list(map(int, row)) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    import numpy as np
    from collections import deque

    a = np.array(grid, dtype=np.uint8)
    h, w = a.shape

    def flood(mask, sx, sy):
        H, W = mask.shape
        seen = np.zeros((H, W), dtype=bool)
        q = deque([(sx, sy)])
        seen[sx, sy] = True
        while q:
            y, x = q.popleft()
            for ny, nx in ((y + 1, x), (y - 1, x), (y, x + 1), (y, x - 1)):
                if 0 <= ny < H and 0 <= nx < W and not seen[ny, nx] and mask[ny, nx]:
                    seen[ny, nx] = True
                    q.append((ny, nx))
        return seen

    # Cells connected to the outer border through non-border cells.
    border_nonzero = a[0, :] | a[-1, :] | a[:, 0] | a[:, -1]
    outside = np.zeros((h, w), dtype=bool)
    for y in range(h):
        for x in range(w):
            if a[y, x] != 0 and not outside[y, x]:
                outside[y, x] = True
                tmp = flood(a != 0, y, x)
                outside |= tmp
    inside = (a != 0) & (~outside)

    # Split the enclosed area into connected "interior" regions.
    labels = np.zeros((h, w), dtype=np.int32)
    region_count = 0
    for y in range(h):
        for x in range(w):
            if inside[y, x] and labels[y, x] == 0:
                region_count += 1
                comp = flood(inside, y, x)
                labels[comp] = region_count

    # For each interior region, take the set of colors that can occur around it.
    # The boundary color of the true pattern box should be one of these, and
    # after removing a rectangular border of that color, the remaining box must
    # not contain that color.
    def border_colors_for_region(reg):
        mask = labels == reg
        colset = set()
        for y in range(h):
            for x in range(w):
                if mask[y, x]:
                    if y > 0 and a[y - 1, x] != a[y, x] and a[y - 1, x] != 0:
                        colset.add(int(a[y - 1, x]))
                    if y + 1 < h and a[y + 1, x] != a[y, x] and a[y + 1, x] != 0:
                        colset.add(int(a[y + 1, x]))
                    if x > 0 and a[y, x - 1] != a[y, x] and a[y, x - 1] != 0:
                        colset.add(int(a[y, x - 1]))
                    if x + 1 < w and a[y, x + 1] != a[y, x] and a[y, x + 1] != 0:
                        colset.add(int(a[y, x + 1]))
        return colset

    def clean_box_for_region(reg, frame):
        mask = labels == reg
        ys, xs = np.where(mask)
        y0, y1 = int(ys.min()), int(ys.max())
        x0, x1 = int(xs.min()), int(xs.max())

        # Shrink a uniform border of the frame color.
        while y0 < y1 and x0 < x1:
            ok = True
            if not np.all(a[y0, x0:x1 + 1] == frame):
                ok = False
            if not np.all(a[y1, x0:x1 + 1] == frame):
                ok = False
            if not np.all(a[y0:y1 + 1, x0] == frame):
                ok = False
            if not np.all(a[y0:y1 + 1, x1] == frame):
                ok = False
            if not ok:
                break
            y0 += 1
            y1 -= 1
            x0 += 1
            x1 -= 1

        # The box must be completely enclosed by that frame color.
        if y1 < y0 or x1 < x0:
            return None
        if not (np.all(a[y0 - 1, x0:x1 + 1] == frame) and
                np.all(a[y1 + 1, x0:x1 + 1] == frame) and
                np.all(a[y0:y1 + 1, x0 - 1] == frame) and
                np.all(a[y0:y1 + 1, x1 + 1] == frame)):
            return None

        inner = a[y0:y1 + 1, x0:x1 + 1]
        if np.any(inner == frame):
            return None

        # Prefer the largest clean inner box; if tied, smaller frame perimeter.
        return (inner.size, (y0, y1, x0, x1))

    boxes = []
    for reg in range(1, region_count + 1):
        for frame in border_colors_for_region(reg):
            got = clean_box_for_region(reg, frame)
            if got is not None:
                boxes.append((got[0], frame, got[1], reg))

    # Deduplicate overlapping boxes, keeping the largest clean inner box.
    boxes.sort(key=lambda t: t[0], reverse=True)
    chosen = []
    for size, frame, rect, reg in boxes:
        y0, y1, x0, x1 = rect
        conflict = False
        for cy0, cy1, cx0, cx1 in chosen:
            # If this box is contained in an already chosen box, skip it.
            if cy0 <= y0 and y1 <= cy1 and cx0 <= x0 and x1 <= cx1:
                conflict = True
                break
        if not conflict:
            chosen.append(rect)

    def infer_periodic_fill(sub):
        H, W = sub.shape
        best = None
        best_metric = None

        max_p = max(1, min(H, max(12, H * 3)))
        max_q = max(1, min(W, max(12, W * 3)))

        # Try small periods first.
        for p in range(1, max_p + 1):
            for q in range(1, max_q + 1):
                if p * q > max(12, H * W):
                    continue

                # Each residue class modulo (p, q) should be almost constant.
                pat = -np.ones((p, q), dtype=np.int8)
                good = True
                diff = 0
                for yy in range(p):
                    for xx in range(q):
                        rows = np.arange(H) % p == yy
                        cols = np.arange(W) % q == xx
                        mask = rows[:, None] & cols[None, :]
                        vals = sub[mask]
                        if vals.size == 0:
                            good = False
                            break
                        uc, cc = np.unique(vals.astype(np.int8), return_counts=True)
                        mc = int(cc.max())
                        if mc * 2 < vals.size:
                            good = False
                            break
                        pat[yy, xx] = int(uc[int(np.argmax(cc))])
                        diff += vals.size - mc
                if not good:
                    continue

                yy_grid, xx_grid = np.meshgrid(np.arange(H), np.arange(W), indexing="ij")
                fill = pat[yy_grid % p, xx_grid % q]
                metric = (diff, p * q, p + q)
                if best_metric is None or metric < best_metric:
                    best_metric = metric
                    best = fill

                # Stop after a very clean tiny period.
                if diff <= max(1, H * W // 50) and p <= 4 and q <= 4:
                    break
            else:
                continue
            break

        return best

    out = a.copy()
    for y0, y1, x0, x1 in chosen:
        sub = a[y0:y1 + 1, x0:x1 + 1].astype(np.int8)
        fill = infer_periodic_fill(sub)
        if fill is not None:
            out[y0:y1 + 1, x0:x1 + 1] = fill.astype(np.uint8)

    return out.astype(int).tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    h, w = len(grid), len(grid[0])
    a = np.array(grid, dtype=int)
    out = a.copy()

    # Most frequent colour is the main background.
    vals, counts = np.unique(a, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    visited = np.zeros((h, w), dtype=bool)

    def add_cell(r, c, color):
        if 0 <= r < h and 0 <= c < w:
            out[r, c] = color

    def paint_corner(r0, c0, color):
        # Draw a 2x2 corner square extending outward from the corner cell.
        if r0 < h and c0 < w:
            out[r0, c0] = color
            if r0 > 0:
                out[r0 - 1, c0] = color
            if c0 > 0:
                out[r0, c0 - 1] = color
            if r0 > 0 and c0 > 0:
                # The fully outward diagonal cell is present only when the
                # path from the seed to the corner has length at least 2.
                if abs(r0 - sr) >= 2 or abs(c0 - sc) >= 2:
                    out[r0 - 1, c0 - 1] = color

    def paint_corner_br(r0, c0, color, sr, sc):
        if r0 < h and c0 < w:
            out[r0, c0] = color
            if r0 + 1 < h:
                out[r0 + 1, c0] = color
            if c0 + 1 < w:
                out[r0, c0 + 1] = color
            if r0 + 1 < h and c0 + 1 < w:
                if abs(r0 - sr) >= 2 or abs(c0 - sc) >= 2:
                    out[r0 + 1, c0 + 1] = color

    def paint_corner_bl(r0, c0, color, sr, sc):
        if r0 < h and c0 > 0:
            out[r0, c0] = color
            if r0 + 1 < h:
                out[r0 + 1, c0] = color
            if c0 > 0:
                out[r0, c0 - 1] = color
            if r0 + 1 < h and c0 > 0:
                if abs(r0 - sr) >= 2 or abs(c0 - sc) >= 2:
                    out[r0 + 1, c0 - 1] = color

    def paint_corner_tr(r0, c0, color, sr, sc):
        if r0 < h and c0 < w:
            out[r0, c0] = color
            if r0 > 0:
                out[r0 - 1, c0] = color
            if c0 + 1 < w:
                out[r0, c0 + 1] = color
            if r0 > 0 and c0 + 1 < w:
                if abs(r0 - sr) >= 2 or abs(c0 - sc) >= 2:
                    out[r0 - 1, c0 + 1] = color

    # Collect all small rectangular 0-bordered rooms.
    for r in range(h - 1):
        for c in range(w - 1):
            if visited[r, c] or a[r, c] != 0:
                continue

            # Find bottom-right of a potential 0 border rectangle.
            br = r
            while br + 1 < h and a[br + 1, c] == 0:
                br += 1
            if br - r < 2:
                continue

            bc = c
            while bc + 1 < w and a[r, bc + 1] == 0:
                bc += 1
            if bc - c < 2:
                continue

            # Validate the whole border.
            ok = True
            for x in range(r, br + 1):
                if a[x, c] != 0 or a[x, bc] != 0:
                    ok = False
                    break
            if not ok:
                continue
            for y in range(c, bc + 1):
                if a[r, y] != 0 or a[br, y] != 0:
                    ok = False
                    break
            if not ok:
                continue

            # Mark visited border cells.
            for x in range(r, br + 1):
                for y in (c, bc):
                    visited[x, y] = True
            for y in range(c, bc + 1):
                for x in (r, br):
                    visited[x, y] = True

            # For every interior non-background seed, connect it to its
            # quadrant corner.
            for rr in range(r + 1, br):
                for cc in range(c + 1, bc):
                    val = int(a[rr, cc])
                    if val == bg or val == 0:
                        continue

                    # Choose quadrant corner.
                    up = rr - r <= br - rr
                    left = cc - c <= bc - cc

                    if up and left:
                        cr, ccorn = r, c
                        # Paint inward diagonal up to the corner.
                        step = 1
                        while rr - step > cr and cc - step > ccorn:
                            add_cell(rr - step, cc - step, val)
                            step += 1
                        paint_corner(cr, ccorn, val)
                    elif up and not left:
                        cr, ccorn = r, bc
                        step = 1
                        while rr - step > cr and cc + step < ccorn:
                            add_cell(rr - step, cc + step, val)
                            step += 1
                        paint_corner_tr(cr, ccorn, val, rr, cc)
                    elif not up and left:
                        cr, ccorn = br, c
                        step = 1
                        while rr + step < cr and cc - step > ccorn:
                            add_cell(rr + step, cc - step, val)
                            step += 1
                        paint_corner_bl(cr, ccorn, val, rr, cc)
                    else:
                        cr, ccorn = br, bc
                        step = 1
                        while rr + step < cr and cc + step < ccorn:
                            add_cell(rr + step, cc + step, val)
                            step += 1
                        paint_corner_br(cr, ccorn, val, rr, cc)

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # Background is the most common colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    def draw_line(r1, c1, r2, c2, color):
        if r1 == r2 or c1 == c2:
            step_r = (r2 - r1)
            step_r //= abs(step_r) if step_r else 0
            step_c = (c2 - c1)
            step_c //= abs(step_c) if step_c else 0
            r, c = r1, c1
            while True:
                if 0 <= r < H and 0 <= c < W:
                    out[r, c] = color
                if r == r2 and c == c2:
                    break
                r += step_r
                c += step_c
        else:
            step_r = 1 if r2 > r1 else -1
            step_c = 1 if c2 > c1 else -1
            r, c = r1, c1
            while r != r2 or c != c2:
                if 0 <= r < H and 0 <= c < W:
                    out[r, c] = color
                r += step_r
                c += step_c
            if 0 <= r < H and 0 <= c < W:
                out[r, c] = color

    # Find all rectangular 0-border frames.  A frame is valid if all four
    # sides are present; missing isolated border cells may be already painted.
    frames = []
    for r in range(H - 2):
        for c in range(W - 2):
            # Top side from (r,c) to the right.
            c2 = c
            while c2 + 1 < W and g[r, c2 + 1] == 0:
                c2 += 1
            if c2 <= c + 1:
                continue
            # Bottom side parallel from (r,c).
            r2 = r
            while r2 + 1 < H and g[r2 + 1, c] == 0:
                r2 += 1
            if r2 <= r + 1:
                continue
            if g[r2, c] != 0 or g[r, c2] != 0:
                continue

            # Verify remaining sides, allowing non-zero cells if they are
            # exactly one per side segment (common for pre-drawn lines).
            left_bad = sum(1 for rr in range(r, r2 + 1) if g[rr, c] != 0)
            right_bad = sum(1 for rr in range(r, r2 + 1) if g[rr, c2] != 0)
            top_bad = sum(1 for cc in range(c, c2 + 1) if g[r, cc] != 0)
            bottom_bad = sum(1 for cc in range(c, c2 + 1) if g[r2, cc] != 0)

            if max(left_bad, right_bad, top_bad, bottom_bad) > 1:
                continue
            if g[r2, c2] != 0:
                continue

            frames.append((r, c, r2, c2))

    # Remove duplicate/nested detections: keep maximal frames only.
    unique_frames = []
    for fr in frames:
        r1, c1, r2, c2 = fr
        contained = False
        for ur in unique_frames:
            ur1, uc1, ur2, uc2 = ur
            if ur1 <= r1 and uc1 <= c1 and ur2 >= r2 and uc2 >= c2:
                contained = True
                break
        if not contained:
            unique_frames.append(fr)
    frames = unique_frames

    processed = set()

    for (r1, c1, r2, c2) in frames:
        corners = [
            (r1, c1, "TL"),
            (r1, c2, "TR"),
            (r2, c1, "BL"),
            (r2, c2, "BR"),
        ]

        # Interior seeds: non-background, non-zero cells strictly inside frame.
        seeds = []
        for rr in range(r1 + 1, r2):
            for cc in range(c1 + 1, c2):
                v = int(g[rr, cc])
                if v == 0 or v == bg:
                    continue
                # Prefer isolated single-cell seeds. If a multi-cell component
                # is present, process only its extreme interior cell in the
                # direction matching its visible diagonal/cap pattern.
                key = None
                if v == g[rr - 1, cc] and rr - 1 > r1:
                    key = (rr - 1, cc)
                elif v == g[rr + 1, cc] and rr + 1 < r2:
                    key = (rr + 1, cc)
                elif v == g[rr, cc - 1] and cc - 1 > c1:
                    key = (rr, cc - 1)
                elif v == g[rr, cc + 1] and cc + 1 < c2:
                    key = (rr, cc + 1)
                elif v == g[rr - 1, cc - 1] and rr - 1 > r1 and cc - 1 > c1:
                    key = (rr - 1, cc - 1)
                elif v == g[rr - 1, cc + 1] and rr - 1 > r1 and cc + 1 < c2:
                    key = (rr - 1, cc + 1)
                elif v == g[rr + 1, cc - 1] and rr + 1 < r2 and cc - 1 > c1:
                    key = (rr + 1, cc - 1)
                elif v == g[rr + 1, cc + 1] and rr + 1 < r2 and cc + 1 < c2:
                    key = (rr + 1, cc + 1)

                if key is not None:
                    # If the neighbour is also an interior seed cell, keep only
                    # the one farthest from the centre of the frame.
                    if (key[0], key[1]) in processed:
                        continue
                    # For now, mark this cell as to be processed unless its
                    # component appears to be a completed line toward a corner.
                    seeds.append((rr, cc, v, key))
                else:
                    seeds.append((rr, cc, v, None))
                    processed.add((rr, cc))

        # For connected multi-cell seeds, select the one closest to a corner.
        grouped = {}
        for rr, cc, v, key in seeds:
            if key is None:
                continue
            if key in grouped:
                grouped[key].append((rr, cc, v))
            else:
                grouped[key] = [(rr, cc, v)]

        selected = []
        for rr, cc, v, key in seeds:
            if key is None:
                selected.append((rr, cc, v))
            elif (rr, cc) in processed:
                continue
            else:
                comp = grouped.get(key, [])
                # Choose the component cell nearest to one of the four corners.
                best = None
                best_d = None
                for (ar, ac, av) in comp:
                    for cr, ccn, _ in corners:
                        d = max(abs(ar - cr), abs(ac - ccn))
                        if best_d is None or d < best_d:
                            best_d = d
                            best = (ar, ac, av)
                selected.append(best)
                for (ar, ac, _) in comp:
                    processed.add((ar, ac))

        for sr, sc, color in selected:
            if (sr, sc) in processed:
                continue
            processed.add((sr, sc))

            # Nearest corner by Chebyshev distance.
            best_corner = None
            best_d = None
            best_name = None
            for cr, cc, name in corners:
                d = max(abs(sr - cr), abs(sc - cc))
                if best_d is None or d < best_d:
                    best_d = d
                    best_corner = (cr, cc)
                    best_name = name
            if best_corner is None:
                continue

            cr, cc = best_corner
            # Paint diagonal from seed to corner.
            draw_line(sr, sc, cr, cc, color)

            # Paint corner cap: corner cell plus outward neighbours.  The
            # diagonal outward cell is painted only if the seed is at least
            # one step away from the corner in both directions.
            out[cr, cc] = color
            if best_name == "TL":
                if cr > 0:
                    out[cr - 1, cc] = color
                if cc > 0:
                    out[cr, cc - 1] = color
                if best_d >= 2:
                    if cr > 0 and cc > 0:
                        out[cr - 1, cc - 1] = color
            elif best_name == "TR":
                if cr > 0:
                    out[cr - 1, cc] = color
                if cc + 1 < W:
                    out[cr, cc + 1] = color
                if best_d >= 2:
                    if cr > 0 and cc + 1 < W:
                        out[cr - 1, cc + 1] = color
            elif best_name == "BL":
                if cr + 1 < H:
                    out[cr + 1, cc] = color
                if cc > 0:
                    out[cr, cc - 1] = color
                if best_d >= 2:
                    if cr + 1 < H and cc > 0:
                        out[cr + 1, cc - 1] = color
            else:  # BR
                if cr + 1 < H:
                    out[cr + 1, cc] = color
                if cc + 1 < W:
                    out[cr, cc + 1] = color
                if best_d >= 2:
                    if cr + 1 < H and cc + 1 < W:
                        out[cr + 1, cc + 1] = color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    A = np.array(grid, dtype=int)
    h, w = A.shape

    # Background is the most frequent border colour.
    bg = int(np.bincount(A.ravel()).argmax())

    # Candidate border colours: non-background colours that can form rectangular
    # corner pieces with at least one interior cell.
    colours = [c for c in range(10) if c != bg and np.count_nonzero(A == c) > 0]
    candidates = []
    for c in colours:
        rows = np.any(A == c, axis=1)
        cols = np.any(A == c, axis=0)
        if not (rows.any() and cols.any()):
            continue
        r0 = int(np.argmax(rows))
        r1 = h - int(np.argmax(rows[::-1])) - 1
        c0 = int(np.argmax(cols))
        c1 = w - int(np.argmax(cols[::-1])) - 1
        sub = A[r0:r1 + 1, c0:c1 + 1]
        sh, sw = sub.shape
        if sh < 3 or sw < 3:
            continue
        top = np.all(sub[0] == c)
        bottom = np.all(sub[-1] == c)
        left = np.all(sub[:, 0] == c)
        right = np.all(sub[:, -1] == c)
        if not ((top and left) or (top and right) or (bottom and left) or (bottom and right)):
            continue
        if (top and left):
            inner = sub[1:-1, 1:-1]
        elif (top and right):
            inner = sub[1:-1, :-1]
        elif (bottom and left):
            inner = sub[:-1, 1:-1]
        else:
            inner = sub[:-1, :-1]
        if inner.size == 0:
            continue
        candidates.append((c, r0, r1, c0, c1, top, bottom, left, right, inner, sub))

    # Choose the colour that gives the most pieces.
    best = None
    for c in colours:
        group = [x for x in candidates if x[0] == c]
        if not group:
            continue
        if best is None or len(group) > len(best[1]):
            best = (c, group)
    if best is None:
        return A.tolist()

    border_colour, pieces = best

    # For each piece, detect the exact corner piece by finding the maximal
    # rectangular region away from the two border sides whose non-background
    # colours are uniform (the piece's interior colour).
    info = []
    for (_, r0, r1, c0, c1, top, bottom, left, right, _, sub) in pieces:
        sh, sw = sub.shape
        if top and left:
            best_h = best_w = 1
            best_col = None
            for hh in range(2, sh):
                for ww in range(2, sw):
                    inner = sub[1:hh, 1:ww]
                    vals = inner[(inner != bg)]
                    if vals.size and len(np.unique(vals)) == 1:
                        best_h, best_w, best_col = hh, ww, int(vals[0])
        elif top and right:
            best_h = best_w = 1
            best_col = None
            for hh in range(2, sh):
                for ww in range(2, sw):
                    inner = sub[1:hh, sw - ww:sw - 1]
                    vals = inner[(inner != bg)]
                    if vals.size and len(np.unique(vals)) == 1:
                        best_h, best_w, best_col = hh, ww, int(vals[0])
        elif bottom and left:
            best_h = best_w = 1
            best_col = None
            for hh in range(2, sh):
                for ww in range(2, sw):
                    inner = sub[sh - hh:sh - 1, 1:ww]
                    vals = inner[(inner != bg)]
                    if vals.size and len(np.unique(vals)) == 1:
                        best_h, best_w, best_col = hh, ww, int(vals[0])
        else:  # bottom and right
            best_h = best_w = 1
            best_col = None
            for hh in range(2, sh):
                for ww in range(2, sw):
                    inner = sub[sh - hh:sh - 1, sw - ww:sw - 1]
                    vals = inner[(inner != bg)]
                    if vals.size and len(np.unique(vals)) == 1:
                        best_h, best_w, best_col = hh, ww, int(vals[0])

        if best_h < 2 or best_w < 2 or best_col is None:
            continue

        piece = np.full((best_h, best_w), bg, dtype=int)
        if top and left:
            piece[0] = border_colour
            piece[:, 0] = border_colour
            piece[1:, 1:] = best_col
            info.append((best_h, best_w, best_col, "TL", piece))
        elif top and right:
            piece[0] = border_colour
            piece[:, -1] = border_colour
            piece[1:, :-1] = best_col
            info.append((best_h, best_w, best_col, "TR", piece))
        elif bottom and left:
            piece[-1] = border_colour
            piece[:, 0] = border_colour
            piece[:-1, 1:] = best_col
            info.append((best_h, best_w, best_col, "BL", piece))
        else:
            piece[-1] = border_colour
            piece[:, -1] = border_colour
            piece[:-1, :-1] = best_col
            info.append((best_h, best_w, best_col, "BR", piece))

    if not info:
        return A.tolist()

    # Keep one piece per corner; prefer the largest interior area.
    chosen = {}
    for hgt, wid, col, corner, piece in info:
        key = corner
        if key not in chosen or hgt * wid > chosen[key][0] * chosen[key][1]:
            chosen[key] = (hgt, wid, col, piece)

    if len(chosen) != 4:
        # Fallback: if not all corners are present, place what exists in its
        # natural corner using the maximum available dimensions.
        H = sum(chosen[k][0] for k in ("TL", "TR", "BL", "BR") if k in chosen)
        W = sum(chosen[k][1] for k in ("TL", "BL") if k in chosen)
        W = max(W, sum(chosen[k][1] for k in ("TR", "BR") if k in chosen))
        out = np.full((H, W), bg, dtype=int)
        y = 0
        for corner, row in (("TL", "TR"), ("BL", "BR")):
            x = 0
            for cc in row:
                if cc in chosen:
                    hgt, wid, col, piece = chosen[cc]
                    out[y:y + hgt, x:x + wid] = piece
                    x += wid
            y += H // 2
        return out.tolist()

    H = chosen["TL"][0] + chosen["BL"][0]
    W = chosen["TL"][1] + chosen["TR"][1]

    out = np.full((H, W), bg, dtype=int)
    out[0:H - chosen["BL"][0], 0:chosen["TL"][1]] = chosen["TL"][3]
    out[0:chosen["TR"][0], chosen["TL"][1]:W] = chosen["TR"][3]
    out[H - chosen["BL"][0]:H, 0:chosen["BL"][1]] = chosen["BL"][3]
    out[H - chosen["BR"][0]:H, chosen["TL"][1]:W] = chosen["BR"][3]

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    A = np.asarray(grid, dtype=int)
    if A.size == 0:
        return []
    H, W = A.shape

    # Background is the most frequent border-touching colour.
    border_vals = np.concatenate((A[0], A[-1], A[:, 0], A[:, -1]))
    vals, counts = np.unique(border_vals, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    def extract_box(mask, r0, c0, r1, c1):
        return A[r0:r1 + 1, c0:c1 + 1][mask[r0:r1 + 1, c0:c1 + 1]]

    def try_add(mask, r0, r1, c0, c1, corner, pieces):
        # Full top and/or bottom rows must contain only the frame colour.
        if not (mask[r0, c0:c1 + 1].all() or mask[r1, c0:c1 + 1].all()):
            return
        if not (mask[r0:r1 + 1, c0].all() or mask[r0:r1 + 1, c1].all()):
            return

        top = mask[r0, c0:c1 + 1].all()
        bottom = mask[r1, c0:c1 + 1].all()
        left = mask[r0:r1 + 1, c0].all()
        right = mask[r0:r1 + 1, c1].all()

        if (top and left):
            pieces[0].add((r0, r1, c0, c1, "TL", extract_box(mask, r0, c0, r1, c1)))
        if (top and right):
            pieces[1].add((r0, r1, c0, c1, "TR", extract_box(mask, r0, c0, r1, c1)))
        if (bottom and left):
            pieces[2].add((r0, r1, c0, c1, "BL", extract_box(mask, r0, c0, r1, c1)))
        if (bottom and right):
            pieces[3].add((r0, r1, c0, c1, "BR", extract_box(mask, r0, c0, r1, c1)))

    # For every colour that appears in the frame, extract every maximal
    # rectangle whose border sides include the colour and that is filled
    # entirely by either that colour or the background.
    candidates = []
    colours = [int(c) for c in np.unique(A) if c != bg and np.any(A == c)]

    for colour in colours:
        frame = (A == colour)
        # A candidate region may contain only the frame colour or background.
        allowed = frame | (A == bg)

        # Maximal rectangles of "allowed" cells.
        for r0 in range(H):
            for c0 in range(W):
                if not allowed[r0, c0]:
                    continue
                # Grow rectangle greedily; this is enough for ARC-sized grids
                # and the pieces are axis-aligned filled rectangles.
                r1 = r0
                while r1 + 1 < H and np.all(allowed[r1 + 1, c0:c1 + 1] if c1 is not None else allowed[r1 + 1, c0:c0 + 1]):
                    r1 += 1
                # Re-grow width for every row to keep the rectangle full.
                changed = True
                while changed:
                    changed = False
                    c1 = W - 1
                    while c1 > c0 and not np.all(allowed[r0:r1 + 1, c1]):
                        c1 -= 1
                    # Ensure the full rectangle is allowed.
                    while not np.all(allowed[r0:r1 + 1, c0:c1 + 1]):
                        # Remove the row/column that breaks it; for these
                        # puzzles the first break is at the right border.
                        c1 -= 1
                        if c1 < c0:
                            break
                    # Grow down again if possible.
                    nr1 = r1
                    while nr1 + 1 < H and np.all(allowed[nr1 + 1, c0:c1 + 1]):
                        nr1 += 1
                    if nr1 != r1:
                        r1 = nr1
                        changed = True

                if r1 <= r0 and c1 <= c0:
                    continue

                # The rectangle must be exactly allowed (no background holes
                # are allowed in the extracted piece region).
                if not np.all(allowed[r0:r1 + 1, c0:c1 + 1]):
                    continue

                # It must contain the frame colour in enough border cells.
                if not frame[r0:r1 + 1, c0:c1 + 1].any():
                    continue

                pieces = [set(), set(), set(), set()]
                try_add(frame, r0, r1, c0, c1, None, pieces)

                for corner, box in zip(("TL", "TR", "BL", "BR"), pieces):
                    for (pr0, pr1, pc0, pc1, _, pbox) in box:
                        candidates.append((corner, pr0, pr1, pc0, pc1, colour, pbox))

    # If the maximal-rectangle pass is too noisy, also try all rectangles
    # directly; grids are small enough for the supplied tasks.
    if len({c for c, *_ in candidates}) < 4:
        candidates = []
        for colour in colours:
            frame = (A == colour)
            allowed = frame | (A == bg)
            for r0 in range(H):
                for r1 in range(r0, H):
                    if not frame[r0, :] .any() and not frame[r1, :].any():
                        continue
                    for c0 in range(W):
                        for c1 in range(c0, W):
                            sub_allowed = allowed[r0:r1 + 1, c0:c1 + 1]
                            sub_frame = frame[r0:r1 + 1, c0:c1 + 1]
                            if not np.all(sub_allowed):
                                continue
                            if not sub_frame.any():
                                continue

                            pieces = [set(), set(), set(), set()]
                            try_add(frame, r0, r1, c0, c1, None, pieces)
                            for corner, box in zip(("TL", "TR", "BL", "BR"), pieces):
                                for (pr0, pr1, pc0, pc1, _, pbox) in box:
                                    candidates.append((corner, pr0, pr1, pc0, pc1, colour, pbox))

    # Choose one piece per corner.  Prefer a colour that supplies all four.
    # Among those, prefer the set with the largest total area, because valid
    # pieces are the maximal corner blocks.
    best_choice = None
    best_score = -1
    for colour in colours:
        choice = {}
        for corner_name, idx in zip(("TL", "TR", "BL", "BR"), range(4)):
            boxes = [c for c in candidates if c[0] == corner_name and c[5] == colour]
            if not boxes:
                continue
            # Prefer the largest valid rectangle of that orientation.
            boxes.sort(key=lambda x: (x[1] - x[0]) * (x[3] - x[2]), reverse=True)
            choice[idx] = boxes[0]
        if len(choice) == 4:
            score = sum((v[1] - v[0] + 1) * (v[3] - v[2] + 1) for v in choice.values())
            if score > best_score:
                best_score = score
                best_choice = choice

    if best_choice is None:
        # Fallback: choose best available pieces even if one corner is missing.
        choice = {}
        for corner_name, idx in zip(("TL", "TR", "BL", "BR"), range(4)):
            boxes = [c for c in candidates if c[0] == corner_name]
            if boxes:
                boxes.sort(key=lambda x: (x[1] - x[0]) * (x[3] - x[2]), reverse=True)
                choice[idx] = boxes[0]
        if not choice:
            return A.tolist()
        best_choice = choice

    # Output dimensions are the sums of widths/heights of the chosen corner
    # pieces.  Missing corners are treated as size zero.
    def piece(idx):
        return best_choice.get(idx, None)

    TL = piece(0)
    TR = piece(1)
    BL = piece(2)
    BR = piece(3)

    h_tl = (TL[1] - TL[0] + 1) if TL else 0
    w_tl = (TL[3] - TL[2] + 1) if TL else 0
    h_tr = (TR[1] - TR[0] + 1) if TR else 0
    w_tr = (TR[3] - TR[2] + 1) if TR else 0
    h_bl = (BL[1] - BL[0] + 1) if BL else 0
    w_bl = (BL[3] - BL[2] + 1) if BL else 0
    h_br = (BR[1] - BR[0] + 1) if BR else 0
    w_br = (BR[3] - BR[2] + 1) if BR else 0

    out_h = max(h_tl + h_bl, h_tr + h_br)
    out_w = max(w_tl + w_tr, w_bl + w_br)
    if out_h == 0 or out_w == 0:
        return A.tolist()

    out = np.full((out_h, out_w), bg, dtype=int)

    if TL is not None:
        out[0:h_tl, 0:w_tl] = TL[6]
    if TR is not None:
        out[0:h_tr, out_w - w_tr:out_w] = TR[6]
    if BL is not None:
        out[out_h - h_bl:out_h, 0:w_bl] = BL[6]
    if BR is not None:
        out[out_h - h_br:out_h, out_w - w_br:out_w] = BR[6]

    return out.tolist()

import numpy as np
from collections import Counter, deque

def _components(mask):
    h, w = mask.shape
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if mask[r, c] and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = [(r, c)]
                while q:
                    y, x = q.popleft()
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and mask[ny, nx] and not seen[ny, nx]:
                            seen[ny, nx] = True
                            q.append((ny, nx))
                            cells.append((ny, nx))
                comps.append(cells)
    return comps

def _bbox(cells):
    rs = [r for r, _ in cells]
    cs = [c for _, c in cells]
    return min(rs), max(rs), min(cs), max(cs)

def _clean_bbox(comp):
    """Trim obvious noise pixels attached by one-cell bridges."""
    r0, r1, c0, c1 = _bbox(comp)
    changed = True
    while changed and r1 > r0 and c1 > c0:
        changed = False
        if r1 - r0 >= 2:
            cnt = sum(1 for r, c in comp if r == r1)
            if cnt <= max(1, (c1 - c0 + 1) // 5):
                r1 -= 1; changed = True
        if r1 > r0 and r1 - r0 >= 2:
            cnt = sum(1 for r, c in comp if r == r0)
            if cnt <= max(1, (c1 - c0 + 1) // 5):
                r0 += 1; changed = True
        if c1 - c0 >= 2:
            cnt = sum(1 for r, c in comp if c == c1)
            if cnt <= max(1, (r1 - r0 + 1) // 5):
                c1 -= 1; changed = True
        if c1 > c0 and c1 - c0 >= 2:
            cnt = sum(1 for r, c in comp if c == c0)
            if cnt <= max(1, (r1 - r0 + 1) // 5):
                c0 += 1; changed = True
    return r0, r1, c0, c1

def _count_compartments(mask, r0, r1, c0, c1):
    if r1 <= r0 + 1 or c1 <= c0 + 1:
        return 0
    sub = np.zeros((r1 - r0 + 1, c1 - c0 + 1), dtype=bool)
    # The frame and its internal walls are solid; background/holes are empty.
    sub[:, :] = ~mask
    # Treat the outer border as closed unless it was genuinely broken by a hole.
    for edge in range(4):
        if edge == 0:
            line = sub[0, :]
        elif edge == 1:
            line = sub[-1, :]
        elif edge == 2:
            line = sub[:, 0]
        else:
            line = sub[:, -1]
        if not line.all():
            line[:] = True
    if not sub.any():
        return 0
    return len(_components(sub))

def _frame_score(comp):
    """Higher is more likely a true rectangular frame."""
    r0, r1, c0, c1 = _bbox(comp)
    h = r1 - r0 + 1
    w = c1 - c0 + 1
    if h < 3 or w < 3:
        return 0
    rect = np.zeros((h, w), dtype=bool)
    for r, c in comp:
        rect[r - r0, c - c0] = True
    perimeter = 2 * (h + w) - 4
    filled = int(rect.sum())
    if filled < perimeter // 2:
        return 0
    # border coverage
    border = rect[0, :] | rect[-1, :] | rect[:, 0] | rect[:, -1]
    border_cells = int(border.sum())
    # interior pixels may be walls, not required to be absent
    return border_cells * 10000 + filled

def _find_frames(grid):
    a = np.array(grid, dtype=int)
    h, w = a.shape
    colors = Counter(a.ravel())
    zero = colors.get(0, 0)
    total = h * w
    color_set = set()
    for c, n in colors.items():
        if c == 0:
            continue
        if n < 8:
            continue
        if n > total * 0.5:
            continue
        color_set.add(c)

    frames = []
    for color in color_set:
        comp = (a == color)
        comps = _components(comp)
        for cells in comps:
            if len(cells) < 8:
                continue
            clean = _clean_bbox(cells)
            score = _frame_score(cells)
            if score <= 0:
                continue
            r0, r1, c0, c1 = clean
            cnt = _count_compartments(comp, r0, r1, c0, c1)
            if cnt <= 0:
                continue
            frames.append((color, r0, r1, c0, c1, cnt))

    if not frames:
        # Fallback: every sufficiently large non-background color component.
        for color in color_set:
            for cells in _components((a == color)):
                if len(cells) >= 8:
                    r0, r1, c0, c1 = _clean_bbox(cells)
                    frames.append((color, r0, r1, c0, c1, 1))
    return frames, a, colors

def transform(grid: list[list[int]]) -> list[list[int]]:
    frames, a, colors = _find_frames(grid)

    if not frames:
        return [[0]]

    # Filler/padding color: the common small "noise" color that is not a frame color.
    frame_colors = {f[0] for f in frames}
    candidates = [(n, c) for c, n in colors.items() if c != 0 and c not in frame_colors]
    # Prefer small but visible noise colors.
    candidates.sort(key=lambda x: (abs(x[1] - max(4, len(a) * len(a) // 200)), x[0]))
    pad = candidates[0][1] if candidates else 5

    # Remove duplicate/contained frame boxes with same color; keep the best.
    best = []
    frames.sort(key=lambda f: -f[5])
    for f in frames:
        ok = True
        for g in best:
            if f[0] == g[0]:
                # If one box contains the other, keep larger/better.
                if (g[1] <= f[1] and g[2] >= f[2] and g[3] <= f[3] and g[4] >= f[4]) or \
                   (f[1] <= g[1] and f[2] >= g[2] and f[3] <= g[3] and f[4] >= g[4]):
                    ok = False
                    break
        if ok:
            best.append(f)

    # Sort by compartment count, then left-to-right, then top-to-bottom.
    best.sort(key=lambda f: (f[5], f[3], f[1], f[0]))

    max_cnt = max(f[5] for f in best)
    width = max(4, max_cnt)

    out = []
    for color, *_ , cnt in best:
        row = [int(color)] * int(cnt)
        row += [int(pad)] * (width - int(cnt))
        out.append(row)

    return out

import numpy as np
from collections import deque

def _components(mask):
    """Return list of cells for 4-connected components of True in mask."""
    h, w = mask.shape
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if mask[r, c] and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = [(r, c)]
                while q:
                    y, x = q.popleft()
                    for dy, dx in ((1,0), (-1,0), (0,1), (0,-1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and mask[ny, nx] and not seen[ny, nx]:
                            seen[ny, nx] = True
                            q.append((ny, nx))
                            cells.append((ny, nx))
                comps.append(cells)
    return comps

def _bbox(cells):
    rs = [r for r, _ in cells]
    cs = [c for _, c in cells]
    return min(rs), max(rs), min(cs), max(cs)

def _clean_bbox(cells):
    """
    Remove thin one-cell protrusions/noise from a frame bounding box.
    This helps when scattered noise pixels touch a frame by a single pixel.
    """
    r0, r1, c0, c1 = _bbox(cells)
    # A real room frame in these puzzles is at least 3x3.
    if r1 - r0 < 2 or c1 - c0 < 2:
        return r0, r1, c0, c1

    changed = True
    while changed:
        changed = False
        if r1 > r0:
            cnt = sum(1 for r, c in cells if r == r1)
            if cnt <= max(1, (c1 - c0 + 1) // 6):
                r1 -= 1
                changed = True
        if r1 > r0:
            cnt = sum(1 for r, c in cells if r == r0)
            if cnt <= max(1, (c1 - c0 + 1) // 6):
                r0 += 1
                changed = True
        if c1 > c0:
            cnt = sum(1 for r, c in cells if c == c1)
            if cnt <= max(1, (r1 - r0 + 1) // 6):
                c1 -= 1
                changed = True
        if c1 > c0:
            cnt = sum(1 for r, c in cells if c == c0)
            if cnt <= max(1, (r1 - r0 + 1) // 6):
                c0 += 1
                changed = True
    return r0, r1, c0, c1

def _is_solid_border(grid, color, r0, r1, c0, c1, threshold=0.65):
    """
    The outer rectangle should be mostly made of the frame color.
    Noise pixels and intersecting other frames may create holes, but not too many.
    """
    h, w = grid.shape
    if r1 <= r0 + 1 or c1 <= c0 + 1:
        return False
    border_cells = []
    for c in range(c0, c1 + 1):
        border_cells.append((r0, c))
        border_cells.append((r1, c))
    for r in range(r0, r1 + 1):
        border_cells.append((r, c0))
        border_cells.append((r, c1))
    good = 0
    for r, c in border_cells:
        if 0 <= r < h and 0 <= c < w and grid[r, c] == color:
            good += 1
    return good / len(border_cells) >= threshold

def _interior_rooms(grid, color, r0, r1, c0, c1):
    """
    Count open interior compartments of one frame.
    Only pixels of the frame color are considered walls.  All other colors
    (including 0, noise, and other object colors) are considered open for
    connectivity.  The outer border is forced to be a wall.
    """
    h = r1 - r0 + 1
    w = c1 - c0 + 1
    if h <= 1 or w <= 1:
        return 0

    open_mask = np.zeros((h, w), dtype=bool)
    for i, r in enumerate(range(r0, r1 + 1)):
        for j, c in enumerate(range(c0, c1 + 1)):
            open_mask[i, j] = (grid[r, c] != color)

    # Force the boundary closed so broken/noisy borders do not leak outside.
    open_mask[0, :] = False
    open_mask[-1, :] = False
    open_mask[:, 0] = False
    open_mask[:, -1] = False

    return len(_components(open_mask))

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    h, w = a.shape

    # Find candidate frame colors.  In the examples frames are the relatively
    # large non-background colors, while the filler/noise color is smaller.
    color_counts = {}
    for val in a.ravel():
        color_counts[int(val)] = color_counts.get(int(val), 0) + 1

    total = h * w
    candidates = []
    for color, cnt in color_counts.items():
        if color == 0:
            continue
        # Ignore tiny specks and very dominant background-like colors.
        if cnt < 8:
            continue
        if cnt > total * 0.45:
            continue
        candidates.append(color)

    objects = []

    for color in candidates:
        mask = (a == color)
        comps = _components(mask)

        # For each large connected component of this color, try its bounding box.
        for cells in comps:
            if len(cells) < 8:
                continue

            r0, r1, c0, c1 = _clean_bbox(cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            if not _is_solid_border(a, color, r0, r1, c0, c1):
                continue

            rooms = _interior_rooms(a, int(color), r0, r1, c0, c1)
            if rooms <= 0:
                continue

            # Keep the largest bounding-box interpretation for this component/color.
            area = (r1 - r0 + 1) * (c1 - c0 + 1)
            objects.append({
                "color": int(color),
                "rooms": int(rooms),
                "r0": int(r0),
                "c0": int(c0),
                "area": int(area),
            })

    # Merge duplicate detections: same color and same/top-left bounding box.
    merged = []
    objects.sort(key=lambda o: (-o["area"], o["r0"], o["c0"], o["color"]))
    for o in objects:
        dup = False
        for m in merged:
            if (
                m["color"] == o["color"]
                and abs(m["r0"] - o["r0"]) <= 2
                and abs(m["c0"] - o["c0"]) <= 2
                and m["area"] >= o["area"] * 0.7
            ):
                dup = True
                break
        if not dup:
            merged.append(o)

    if not merged:
        return [[0]]

    # Choose the filler/padding color: the common non-frame color that is not
    # part of a detected object.  In examples this is the small scattered noise.
    frame_colors = {o["color"] for o in merged}
    filler = 5
    best_score = None
    for color, cnt in color_counts.items():
        if color == 0 or color in frame_colors:
            continue
        # Prefer small visible colors; the noise color is typically small.
        score = (cnt, -color)
        if best_score is None or score < best_score:
            best_score = score
            filler = int(color)

    # Sort rows by room count.  For ties, use top-to-bottom, left-to-right.
    merged.sort(key=lambda o: (o["rooms"], o["r0"], o["c0"], o["color"]))

    max_rooms = max(o["rooms"] for o in merged)
    width = max(4, max_rooms)

    out = []
    for o in merged:
        row = [o["color"]] * o["rooms"]
        row += [filler] * (width - o["rooms"])
        out.append(row)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    grid = [list(row) for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0

    # Determine candidate "main" colours: colours that form relatively large
    # connected components and are not background.
    def components(color):
        seen = [[False] * w for _ in range(h)]
        comps = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] == color and not seen[r][c]:
                    stack = [(r, c)]
                    seen[r][c] = True
                    cells = []
                    while stack:
                        x, y = stack.pop()
                        cells.append((x, y))
                        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < h and 0 <= ny < w and not seen[nx][ny] and grid[nx][ny] == color:
                                seen[nx][ny] = True
                                stack.append((nx, ny))
                    comps.append(cells)
        return comps

    main_colors = set()
    for color in set(x for row in grid for x in row if x != 0):
        comps = components(color)
        if max(len(c) for c in comps) >= 3:
            main_colors.add(color)

    best = None

    # Try each ordered pair of colours (main shape colour, marker colour).
    for main_color in main_colors:
        marker_candidates = [c for c in set(x for row in grid for x in row if x != 0)
                             if c != main_color and c not in main_colors]
        for marker_color in marker_candidates:
            main_cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == main_color]
            marker_cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker_color]
            if not main_cells or not marker_cells:
                continue

            min_r = min(r for r, _ in main_cells)
            max_r = max(r for r, _ in main_cells)
            min_c = min(c for _, c in main_cells)
            max_c = max(c for _, c in main_cells)

            # Direction: one of the four orthogonal directions from the shape
            # to its exterior.
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                # The line on which markers are projected must be a row/col
                # parallel to the movement direction and touching the shape.
                if dr == -1:
                    line = min_r - 1
                    if line < 0:
                        continue
                    coords = [(line, c) for _, c in marker_cells]
                    length = len(set(c for _, c in coords))
                    # Choose the column of the output segment by aligning the
                    # projected marker columns with the segment start.
                    if not length:
                        continue
                    seg_cols = sorted(set(c for _, c in coords))
                    # The segment is placed adjacent to the shape, preserving
                    # the relative order of marker columns.
                    start_col = min_c - (length - 1) if dc == -1 else max_c + 1
                    # If markers are to the right, place just right; if to the
                    # left, place just left.  This rule is verified on all examples.
                    if dc == 1:
                        start_col = max_c + 1
                    elif dc == -1:
                        start_col = min_c - length
                    cells = [(line, start_col + i) for i in range(length)]
                    if any(not (0 <= r < h and 0 <= c < w) for r, c in cells):
                        continue
                    if any(grid[r][c] not in (0, marker_color) for r, c in cells):
                        continue
                    # All marker cells must be removed; the new cells must not
                    # overwrite non-marker/non-background cells.
                    out = [row[:] for row in grid]
                    for r, c in marker_cells:
                        out[r][c] = 0
                    ok = True
                    for r, c in cells:
                        if out[r][c] not in (0, marker_color):
                            ok = False
                            break
                    if not ok:
                        continue
                    for r, c in cells:
                        out[r][c] = marker_color
                    # Scoring: reward output cells near the shape and marker cells
                    # that are actually moved outside the original main bbox.
                    score = 0
                    for r, c in cells:
                        score += 1
                    score -= 10 * sum(1 for r, c in cells if min_r <= r <= max_r and min_c <= c <= max_c)
                    if best is None or score > best[0]:
                        best = (score, out)
                elif dr == 1:
                    line = max_r + 1
