                        continue
                    coords = [(line, c) for _, c in marker_cells]
                    length = len(set(c for _, c in coords))
                    if not length:
                        continue
                    if dc == 0:
                        # vertical placement: use column of shape closest to markers
                        start_col = min_c
                    if dc == 1:
                        start_col = max_c + 1
                    elif dc == -1:
                        start_col = min_c - length
                    else:
                        start_col = min_c
                    cells = [(line, start_col + i) for i in range(length)]
                    if any(not (0 <= r < h and 0 <= c < w) for r, c in cells):
                        continue
                    if any(grid[r][c] not in (0, marker_color) for r, c in cells):
