                    score = len(cells)
                    score -= 10 * sum(1 for r, c in cells if min_r <= r <= max_r and min_c <= c <= max_c)
                    if best is None or score > best[0]:
                        best = (score, out)
                elif dc == -1:
                    line = min_c - 1
                    if line < 0:
                        continue
                    coords = [(r, line) for r, _ in marker_cells]
                    length = len(set(r for r, _ in coords))
                    if not length:
                        continue
                    start_row = min_r
                    if dr == -1:
                        start_row = min_r
                    elif dr == 1:
                        start_row = max_r - length + 1
                    else:
                        # choose row closest to marker rows
                        start_row = min(min_r, max_r - length + 1)
                    cells = [(start_row + i, line) for i in range(length)]
                    if any(not (0 <= r < h and 0 <= c < w) for r, c in cells):
                        continue
                    if any(grid[r][c] not in (0, marker_color) for r, c in cells):
                        continue
                    out = [row[:] for row in grid]
                    for r, c in marker_cells:
